PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE news (
  id            TEXT    PRIMARY KEY,              -- newsId
  title         TEXT    NOT NULL,
  summary       TEXT    NOT NULL DEFAULT '',
  url           TEXT    NOT NULL,
  kind          TEXT    NOT NULL DEFAULT 'off',   -- off 官方公告 | fix 熱修 | blue 藍帖 | site 本站
  category      TEXT    NOT NULL DEFAULT '',
  published_at  INTEGER NOT NULL,                 -- lastUpdated（unix 秒）
  first_seen_at INTEGER NOT NULL,
  updated_at    INTEGER NOT NULL
, image TEXT NOT NULL DEFAULT '', extra TEXT NOT NULL DEFAULT '');
