INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24313102','《魔獸世界》新聞焦點《至暗之夜》12.1.5、世界之核、《魔獸世界：永恆》等豐富內容','本週新聞滿載嶄新內容！從《至暗之夜》的全新挑戰，到搶先一窺「世界之核回音」的未來內容，再到「聖騎士」深入解析，以及最新的《魔獸世界：永恆》Podcast，還有全新獎勵與更多艾澤拉斯冒險等你來探索。','https://news.blizzard.com/zh-tw/article/24313102/12-1-5','off','本週《魔獸世界》新聞',1792170000,1792322139,1793030455,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/95/9529MJQ6I5D81792108492179.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24302072','[10 月 19 日更新] 加入《魔獸世界：永恆》壓力測試','《魔獸世界：永恆》壓力測試的大門開啟了。10 月 22 開始的限定期間內，所有感興趣的玩家皆可登入《魔獸世界：永恆》，幫助我們測試伺服器。所有人都可參加，無需訂閱服務、遊戲時間、邀請函，或是 Beta 測試資格。','https://news.blizzard.com/zh-tw/article/24302072/10-19','off','最新消息',1792098000,1792322139,1793030455,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/ev/EVFNPP5S77ZN1789667878336.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24302099','《魔獸世界：永恆》職業深入解析：聖騎士','在《魔獸世界：永恆》職業深入解析中，化身為聖光勇士。探索聖騎士的改動會如何強化該職業獨一無二的聖印與審判，同時拓展神聖治療與法術傷害、防護坦克，以及懲戒傷害的全新手段。','https://news.blizzard.com/zh-tw/article/24302099/%E3%80%8A%E9%AD%94%E7%8D%B8%E4%B8%96%E7%95%8C%EF%BC%9A%E6%B0%B8%E6%81%86%E3%80%8B%E8%81%B7%E6%A5%AD%E6%B7%B1%E5%85%A5%E8%A7%A3%E6%9E%90%EF%BC%9A%E8%81%96%E9%A8%8E%E5%A3%AB','off','最新消息',1792090800,1792322139,1793030455,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/l4/L48SD06IA9HZ1791582782982.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24304079','觀看《魔獸世界：永恆》Podcast Ep. 4，一同探索 PvP 玩法','在本集《魔獸世界：永恆》Podcast 中，主持人 Countdown To Classic、特別來賓 Savix 和 Tips Out，以及資深遊戲設計師 Josh "Aggrend" Greenfield 與首席設計師 Tim Jones 展開討論，深入探討《魔獸世界：永恆》中的玩家對玩家（PvP）玩法。','https://news.blizzard.com/zh-tw/article/24304079/podcast-ep-4-pvp','off','最新消息',1792080900,1792322139,1793030455,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/j4/J4VL3VN3Q09U1792006355845.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24310653','立即觀賞《魔獸世界：永恆》Podcast Ep. 3','在本集《魔獸世界：永恆》Podcast 中，主持人 Countdown To Classic、特別來賓 Hammerdance，以及資深遊戲設計師 Josh "Aggrend" Greenfield、Jay Hartman 與 Rowan Ryder 展開討論，深入探討地城升級、任務設計等精彩內容。','https://news.blizzard.com/zh-tw/article/24310653/podcast-ep-3','off','最新消息',1791476700,1792322139,1793030455,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/ne/NEB3O3XOQIAH1791477877824.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24310968','《魔獸世界：永恆》職業深入解析：盜賊與術士','在本次的《魔獸世界：永恆》職業深入解析中，精通詭秘技巧與毀滅力量的大師將成為討論的焦點。一起來看看盜賊與術士的更新，如何強化各職業獨具特色的技能、戰術與玩法。','https://news.blizzard.com/zh-tw/article/24310968/%E3%80%8A%E9%AD%94%E7%8D%B8%E4%B8%96%E7%95%8C%EF%BC%9A%E6%B0%B8%E6%81%86%E3%80%8B%E8%81%B7%E6%A5%AD%E6%B7%B1%E5%85%A5%E8%A7%A3%E6%9E%90%EF%BC%9A%E7%9B%9C%E8%B3%8A%E8%88%87%E8%A1%93%E5%A3%AB','off','最新消息',1791410400,1792322139,1792774856,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/ny/NYO22B3CT06C1791322589103.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24302097','《魔獸世界：永恆》深入解析：法師與薩滿','我們的《魔獸世界：永恆》職業深入解析系列將繼續連載，這次要與開發者一起探索法師與薩滿。了解法師更新將如何拓展秘法、火焰，以及冰霜魔法，帶來例如霜火箭的全新混合可能性。並了解薩滿的改動將如何讓圖騰管理變得更加輕鬆，武器灌魔效果持續時間延長，以及元素戰鬥、增強，和恢復的流派會如何變得更加多元。','https://news.blizzard.com/zh-tw/article/24302097/%E3%80%8A%E9%AD%94%E7%8D%B8%E4%B8%96%E7%95%8C%EF%BC%9A%E6%B0%B8%E6%81%86%E3%80%8B%E6%B7%B1%E5%85%A5%E8%A7%A3%E6%9E%90%EF%BC%9A%E6%B3%95%E5%B8%AB%E8%88%87%E8%96%A9%E6%BB%BF','off','最新消息',1791410400,1792322139,1793030455,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/w3/W3CHYFXZK02H1791309672171.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24302546','《魔獸世界：永恆》- 天裔精靈視覺更新的未來','跟著《魔獸世界》開發團隊，了解他們如何調整天裔精靈視覺風格、重新審視高解析度德魯伊形態，以及如何透過標準解析度角色模型為玩家帶來更多選擇。','https://news.blizzard.com/zh-tw/article/24302546/%E3%80%8A%E9%AD%94%E7%8D%B8%E4%B8%96%E7%95%8C%EF%BC%9A%E6%B0%B8%E6%81%86%E3%80%8B-+%E5%A4%A9%E8%A3%94%E7%B2%BE%E9%9D%88%E8%A6%96%E8%A6%BA%E6%9B%B4%E6%96%B0%E7%9A%84%E6%9C%AA%E4%BE%86','off','最新消息',1791406800,1792322139,1792774856,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/sr/SRGU8HIDWYQU1791312885139.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24307308','參與《魔獸世界：永恆》的暗矛島嶼之戰','在《魔獸世界：永恆》的全新 15v15 戰場「暗矛島嶼」爭奪地盤，加入暗矛劫掠者或塞拉摩遠征軍，在此奪取戰略據點並佔領旗幟，賺取聲望獎勵。','https://news.blizzard.com/zh-tw/article/24307308/%E5%8F%83%E8%88%87%E3%80%8A%E9%AD%94%E7%8D%B8%E4%B8%96%E7%95%8C%EF%BC%9A%E6%B0%B8%E6%81%86%E3%80%8B%E7%9A%84%E6%9A%97%E7%9F%9B%E5%B3%B6%E5%B6%BC%E4%B9%8B%E6%88%B0','off','最新消息',1791399600,1792322139,1792685756,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/u1/U1OSIX5Z8I5Z1790889139088.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24303316','《魔獸世界：永恆》的 PvP 進度系統介紹','《魔獸世界：永恆》的 PvP (玩家對玩家) 進度系統經過重新設計，讓榮譽值、軍銜點數、賽季目標，和各位所熟悉的原版排名更容易理解。玩家可透過戰場、PvP 任務、每週旅程任務，以及裝備升級獲得獎勵，同時爭取高階督軍和總元帥等經典頭銜。','https://news.blizzard.com/zh-tw/article/24303316/pvp','off','最新消息',1791392400,1792322139,1792612856,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/ow/OWXLE8T6SV3O1790901629869.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24310649','《魔獸世界：永恆》的各職業是本週《魔獸世界》新聞的焦點','新的一週到來，就表示《魔獸世界》有更多東西在等你發掘。探索最新的《魔獸世界：永恆》職業聚焦，本期重點介紹獵人、德魯伊、牧師和戰士，也別忘了鎖定《魔獸世界：永恆》Podcast Ep. 2。那麼，趕快來看看《至暗之夜》12.1.5 更新會帶來哪些新內容吧。在本週的《魔獸世界》新聞探索全部內容。','https://news.blizzard.com/zh-tw/article/24310649/%E3%80%8A%E9%AD%94%E7%8D%B8%E4%B8%96%E7%95%8C%EF%BC%9A%E6%B0%B8%E6%81%86%E3%80%8B%E7%9A%84%E5%90%84%E8%81%B7%E6%A5%AD%E6%98%AF%E6%9C%AC%E9%80%B1%E3%80%8A%E9%AD%94%E7%8D%B8%E4%B8%96%E7%95%8C%E3%80%8B%E6%96%B0%E8%81%9E%E7%9A%84%E7%84%A6%E9%BB%9E','off','本週《魔獸世界》新聞',1790960400,1792322139,1792522856,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/h6/H6XDU3AJJRCK1790899066898.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24298592','立即觀賞！《魔獸世界：永恆》Podcast Ep.2，適合快速通關的職業','由主持人 Countdown To Classic、資深遊戲設計師 Josh "Aggrend" Greenfield、核心遊戲設計師 Kris Zierhut、資深遊戲設計師 Aidan Moon，以及特別來賓與內容創作者 Sodapoppin 為大家帶來精彩討論。','https://news.blizzard.com/zh-tw/article/24298592/podcast-ep-2','off','最新消息',1790871300,1792322139,1792452628,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/x3/X3B1QPIB3A0E1790880532807.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24301514','《魔獸世界：永恆》深入解析：牧師與戰士','牧師和戰士是接下來在《魔獸世界：永恆》深入解析中要介紹的職業，其中包含各項更新，這些更新都基於玩家所熟悉的角色定位、戰鬥節奏，以及職業招牌工具之上。這篇搶先一窺文章會介紹全新與調整過的基本技能、更新過的種族牧師法術、戰士怒氣和姿態更新、以及戒律、神聖、暗影、武器、狂怒、防護天賦的改動。','https://news.blizzard.com/zh-tw/article/24301514/%E3%80%8A%E9%AD%94%E7%8D%B8%E4%B8%96%E7%95%8C%EF%BC%9A%E6%B0%B8%E6%81%86%E3%80%8B%E6%B7%B1%E5%85%A5%E8%A7%A3%E6%9E%90%EF%BC%9A%E7%89%A7%E5%B8%AB%E8%88%87%E6%88%B0%E5%A3%AB','off','最新消息',1790802000,1792322139,1792374322,'','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2383617','WoW Forever Stress Test October 21','UPDATE – This test is now taking place on October 21 Please join us for the WoW Forever Stress Test on October 21. On that day, we will first take the WoW Forever Beta offline, and we will then open WoW Forever on the regional hardware that it will operate on when the game goes live. On October 21…','https://us.forums.blizzard.com/en/wow/t/wow-forever-stress-test-october-21/2383617','blue','官方論壇',1792190395,1792404656,1792688456,'','[{"n":1,"at":1792099481,"user":"Kaivax","text":"UPDATE – This test is now taking place on October 21 Please join us for the WoW Forever Stress Test on October 21. On that day, we will first take the WoW Forever Beta offline, and we will then open WoW Forever on the regional hardware that it will operate on when the game goes live. On October 21…","url":"https://us.forums.blizzard.com/en/wow/t/wow-forever-stress-test-october-21/2383617/1"},{"n":39,"at":1792190395,"user":"Kaivax","text":"Please note that we will do the Stress Test on October 21, not two days earlier as previously stated. Thank you!","url":"https://us.forums.blizzard.com/en/wow/t/wow-forever-stress-test-october-21/2383617/39"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2384010','Druid cat form quest','We sent a hotfix to the Beta a few minutes ago that fixed the bug preventing druids from looting the relics necessary to acquire Cat Form. Thank you for the bug reports.','https://us.forums.blizzard.com/en/wow/t/druid-cat-form-quest/2384010','blue','官方論壇',1792173398,1792404656,1792632655,'','[{"n":56,"at":1792173398,"user":"Kaivax","text":"We sent a hotfix to the Beta a few minutes ago that fixed the bug preventing druids from looting the relics necessary to acquire Cat Form. Thank you for the bug reports.","url":"https://us.forums.blizzard.com/en/wow/t/druid-cat-form-quest/2384010/56"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2383475','Beta Realm Maintenance - October 15','We’re planning to take the WoW Forever Beta down in about 15 minutes, at 1:15 p.m. PDT. This will be a maintenance period that includes deploying and testing a new build of the game, and that build has quite a few changes and fixes. We’ll have a full update to the Development Notes for you when we…','https://us.forums.blizzard.com/en/wow/t/beta-realm-maintenance-october-15/2383475','blue','官方論壇',1792112804,1792404656,1792599356,'','[{"n":1,"at":1792094423,"user":"Kaivax","text":"We’re planning to take the WoW Forever Beta down in about 15 minutes, at 1:15 p.m. PDT. This will be a maintenance period that includes deploying and testing a new build of the game, and that build has quite a few changes and fixes. We’ll have a full update to the Development Notes for you when we…","url":"https://us.forums.blizzard.com/en/wow/t/beta-realm-maintenance-october-15/2383475/1"},{"n":1169,"at":1792112804,"user":"Zorbrix-83447","text":"Realms are back up from maintenance, thanks for being patient while we got this build out the door. If you’re not on client 70425, make sure you exit the game and update via the bnet app.","url":"https://us.forums.blizzard.com/en/wow/t/beta-realm-maintenance-october-15/2383475/1169"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2360696','WoW Forever Beta Development Notes – Updated October 15','Today, we updated the WoW Forever Beta with a new build that includes the following updates. Change Log Bugfixes Fixed a bug with casters not playing their precast animations and sometimes standing while casting. Changed the sound effect that plays while jumping in water to be more aesthetically …','https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-development-notes-%E2%80%93-updated-october-15/2360696','blue','官方論壇',1792109723,1792404656,1792540856,'','[{"n":1,"at":1790288604,"user":"Kaivax","text":"Today, we updated the WoW Forever Beta with a new build that includes the following updates. Change Log Bugfixes Fixed a bug with casters not playing their precast animations and sometimes standing while casting. Changed the sound effect that plays while jumping in water to be more aesthetically …","url":"https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-development-notes-%E2%80%93-updated-october-15/2360696/1"},{"n":4,"at":1790895364,"user":"Kaivax","text":"Today, we updated the WoW Forever Beta with a new build that includes the following. CHANGE LOG Bug Fixes Improved rain visibility. Removed the ‘Ray Traced Shadows’ option. This setting will be re-added to the game in a future update, after the functionality is fixed. Fixed an issue where the Nig…","url":"https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-development-notes-%E2%80%93-updated-october-15/2360696/4"},{"n":5,"at":1791495158,"user":"Kaivax","text":"Today, we updated the WoW Forever Beta with a new build that includes the following. CHANGE LOG Bug Fixes This build reintroduces Classic looting behavior, where creatures that dropped no loot can still be interacted with. Fixed visual effects flickering on large creatures. Fixed creature behavio…","url":"https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-development-notes-%E2%80%93-updated-october-15/2360696/5"},{"n":6,"at":1792109723,"user":"Kaivax","text":"We’ve updating the WoW Forever Beta with a new build that includes the following. CHANGE LOG Bug Fixes Resolved an issue with extra bright fog at lower shadow settings. Fixed an issue allowing Horde players to gain Kirin Tor reputation. Creatures will now properly regenerate health when out of c…","url":"https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-development-notes-%E2%80%93-updated-october-15/2360696/6"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2382032','Beta Maintenance - October 14','We’re taking the WoW Forever Beta offline in a few minutes for maintenance. We’re going to run some internal tests, and we don’t expect it to be down for more than a couple of hours. Beta realms should go offline at 8:00 a.m. PDT. We’ll see you on the other side!','https://us.forums.blizzard.com/en/wow/t/beta-maintenance-october-14/2382032','blue','官方論壇',1791993038,1792404656,1792441144,'','[{"n":1,"at":1791989389,"user":"Kaivax","text":"We’re taking the WoW Forever Beta offline in a few minutes for maintenance. We’re going to run some internal tests, and we don’t expect it to be down for more than a couple of hours. Beta realms should go offline at 8:00 a.m. PDT. We’ll see you on the other side!","url":"https://us.forums.blizzard.com/en/wow/t/beta-maintenance-october-14/2382032/1"},{"n":79,"at":1791993038,"user":"Kaivax","text":"The Beta is coming back online imminently.","url":"https://us.forums.blizzard.com/en/wow/t/beta-maintenance-october-14/2382032/79"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2352687','WoW Forever Beta Known Issues - October 8','We’re opening the WoW Forever Beta today with the following known issues. Known Issues September 18, 2026 Barber Chairs cause a LUA error. Character friends in Beta disabled. The minimap may be partially off the screen. Waylaid Crates do not function on items with a maximum stack size smaller tha…','https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-known-issues-october-8/2352687','blue','官方論壇',1791495520,1792404656,1792441144,'','[{"n":1,"at":1789681676,"user":"Kaivax","text":"We’re opening the WoW Forever Beta today with the following known issues. Known Issues September 18, 2026 Barber Chairs cause a LUA error. Character friends in Beta disabled. The minimap may be partially off the screen. Waylaid Crates do not function on items with a maximum stack size smaller tha…","url":"https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-known-issues-october-8/2352687/1"},{"n":4,"at":1789754548,"user":"Kaivax","text":"Added to the list above: The Cooldown Manager is a work in progress. Complete implementation varies from class to class. Armor bonuses from consumables and buffs are multiplied by Bear Form armor bonuses. Queueing an On-Next Attack ability (Heroic Strike/Cleave/Raptor Strike) disables your spell q…","url":"https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-known-issues-october-8/2352687/4"},{"n":5,"at":1790289051,"user":"Kaivax","text":"Resolved Issues Teldrassil - During the quest “Escaping Ban’ethil”, Sentinel Lynessa Duskblossom runs a bit too fast and spams her Strike ability. This is fixed in the next beta build. Loch Modan - “Snowbound” gives more XP than intended. This is adjusted in the next beta build. Known Issues - New…","url":"https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-known-issues-october-8/2352687/5"},{"n":6,"at":1790895419,"user":"Kaivax","text":"Known Issues - New October 1 Chaining Spells together does not play the precast spell effects and sounds of the next cast until the first cast finishes. For example: When you cast Fireball and cast another Fireball right away, you finish your Fireball cast, your hands won’t glow or make the crack…","url":"https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-known-issues-october-8/2352687/6"},{"n":7,"at":1791495520,"user":"Kaivax","text":"Known Issues - New October 8 • While texture updates to Skyborne druid bear and travel form are updated, texture updates to Skyborne druid cat form, various creatures in Zephras Isle, and some mounts, pets, and other creatures will arrive in a future build. • Hunters who selected the Ferocity tale…","url":"https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-known-issues-october-8/2352687/7"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2375900','Beta Realm Maintenance - October 8','Starting in one hour at 9:00 a.m. PDT, we will take the WoW Forever Beta down for maintenance and updates. We’re starting a bit earlier today than we have on previous Thursdays, because we’ve gathered up several fixes for behind-the-scenes, non-gameplay issues that we’re going to deploy and then tes…','https://us.forums.blizzard.com/en/wow/t/beta-realm-maintenance-october-8/2375900','blue','官方論壇',1791495246,1792404656,1792441144,'','[{"n":1,"at":1791471521,"user":"Kaivax","text":"Starting in one hour at 9:00 a.m. PDT, we will take the WoW Forever Beta down for maintenance and updates. We’re starting a bit earlier today than we have on previous Thursdays, because we’ve gathered up several fixes for behind-the-scenes, non-gameplay issues that we’re going to deploy and then tes…","url":"https://us.forums.blizzard.com/en/wow/t/beta-realm-maintenance-october-8/2375900/1"},{"n":551,"at":1791495246,"user":"Kaivax","text":"Beta realm is back! Here are some notes.","url":"https://us.forums.blizzard.com/en/wow/t/beta-realm-maintenance-october-8/2375900/551"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2374348','Brief Beta Realm Maintenance - October 6','We’re planning to do realm restarts at 3:00 p.m. PDT (about 40 minutes from now), to pick up some priority fixes for the Beta. One of the fixes is intended to address quests where quest items are intended to be restocked in a chest, but have gone missing. If you’re in-game in the WoW: Forever Beta…','https://us.forums.blizzard.com/en/wow/t/brief-beta-realm-maintenance-october-6/2374348','blue','官方論壇',1791323574,1792404656,1792441144,'','[{"n":1,"at":1791321640,"user":"Kaivax","text":"We’re planning to do realm restarts at 3:00 p.m. PDT (about 40 minutes from now), to pick up some priority fixes for the Beta. One of the fixes is intended to address quests where quest items are intended to be restocked in a chest, but have gone missing. If you’re in-game in the WoW: Forever Beta…","url":"https://us.forums.blizzard.com/en/wow/t/brief-beta-realm-maintenance-october-6/2374348/1"},{"n":3,"at":1791323574,"user":"Kaivax","text":"A couple more fixes going in with this restart: Fixed a bug that could occasionally disconnect you when riding an elevator or transport. Addressed an error that could occur when joining or leaving a guild.","url":"https://us.forums.blizzard.com/en/wow/t/brief-beta-realm-maintenance-october-6/2374348/3"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2373436','Brief Realm Maintenance - October 5','We’re going to do realm restarts in a few minutes, to apply some fixes that should improve the quality of the game service. Beta testers who are in-game will see server messages counting down to the restart time. And the Beta will re-open a few minutes after it goes offline.','https://us.forums.blizzard.com/en/wow/t/brief-realm-maintenance-october-5/2373436','blue','官方論壇',1791242277,1792404656,1792441144,'','[{"n":1,"at":1791242277,"user":"Kaivax","text":"We’re going to do realm restarts in a few minutes, to apply some fixes that should improve the quality of the game service. Beta testers who are in-game will see server messages counting down to the restart time. And the Beta will re-open a few minutes after it goes offline.","url":"https://us.forums.blizzard.com/en/wow/t/brief-realm-maintenance-october-5/2373436/1"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2370922','Gnomeregan, Who broke it?!','Who broke it? Gnomes, of course. But earlier this afternoon, we fixed it. Thanks for your reports!','https://us.forums.blizzard.com/en/wow/t/gnomeregan-who-broke-it/2370922','blue','官方論壇',1791072474,1792404656,1792441144,'','[{"n":6,"at":1791072474,"user":"Kaivax","text":"Who broke it? Gnomes, of course. But earlier this afternoon, we fixed it. Thanks for your reports!","url":"https://us.forums.blizzard.com/en/wow/t/gnomeregan-who-broke-it/2370922/6"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2368931','Dialog Bug for Australian Testers -- fixed','Update 04:00 AEDT October 4 We’ve fixed the bug that was causing this. With the new build of the WoW Forever Beta, we have an unexpected bug where Australian players are being presented with a dialog when they log in telling them their social features are locked down. This is not the case, of cour…','https://us.forums.blizzard.com/en/wow/t/dialog-bug-for-australian-testers-fixed/2368931','blue','官方論壇',1791048890,1792404656,1792441144,'','[{"n":1,"at":1790896138,"user":"Kaivax","text":"Update 04:00 AEDT October 4 We’ve fixed the bug that was causing this. With the new build of the WoW Forever Beta, we have an unexpected bug where Australian players are being presented with a dialog when they log in telling them their social features are locked down. This is not the case, of cour…","url":"https://us.forums.blizzard.com/en/wow/t/dialog-bug-for-australian-testers-fixed/2368931/1"},{"n":217,"at":1791048890,"user":"Kaivax","text":"We’ve fixed the bug that was causing this.","url":"https://us.forums.blizzard.com/en/wow/t/dialog-bug-for-australian-testers-fixed/2368931/217"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2369360','Warrior Updates in Today''s Beta Build','A number of additional updates for Warriors in WoW Forever made it into today’s new Beta build, and we just added all of the following to our Development Notes for today. Warrior Additional Rage generated from landing Critical Strikes increased to 100% increased Rage (was 75%). Fixed a bug that w…','https://us.forums.blizzard.com/en/wow/t/warrior-updates-in-todays-beta-build/2369360','blue','官方論壇',1790909861,1792404656,1792441144,'','[{"n":1,"at":1790909861,"user":"Kaivax","text":"A number of additional updates for Warriors in WoW Forever made it into today’s new Beta build, and we just added all of the following to our Development Notes for today. Warrior Additional Rage generated from landing Critical Strikes increased to 100% increased Rage (was 75%). Fixed a bug that w…","url":"https://us.forums.blizzard.com/en/wow/t/warrior-updates-in-todays-beta-build/2369360/1"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2369114','Beta Service Issue - October 1','We’re aware of and working to address an issue that appears to be preventing testers from logging into the WoW: Forever Beta. We will continue to work to fix this as swiftly as possible.','https://us.forums.blizzard.com/en/wow/t/beta-service-issue-october-1/2369114','blue','官方論壇',1790899402,1792404656,1792441144,'','[{"n":1,"at":1790899402,"user":"Kaivax","text":"We’re aware of and working to address an issue that appears to be preventing testers from logging into the WoW: Forever Beta. We will continue to work to fix this as swiftly as possible.","url":"https://us.forums.blizzard.com/en/wow/t/beta-service-issue-october-1/2369114/1"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2368776','Legacy Points for Beta Testing','Over the first two weeks of the WoW Forever Beta, we’ve seen an increasing number of testers pushing to earn points in the Legacy system. In a future week of the Beta, we’re planning to grant all testers 16 Legacy points so that the system can be tested without first requiring a great deal of level…','https://us.forums.blizzard.com/en/wow/t/legacy-points-for-beta-testing/2368776','blue','官方論壇',1790891649,1792404656,1792441144,'','[{"n":1,"at":1790891649,"user":"Kaivax","text":"Over the first two weeks of the WoW Forever Beta, we’ve seen an increasing number of testers pushing to earn points in the Legacy system. In a future week of the Beta, we’re planning to grant all testers 16 Legacy points so that the system can be tested without first requiring a great deal of level…","url":"https://us.forums.blizzard.com/en/wow/t/legacy-points-for-beta-testing/2368776/1"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2367661','Beta Update Maintenance - October 1','Tomorrow morning PDT, we will take the WoW Forever Beta offline for maintenance. Several hours later, the Beta will resume with an updated build that includes changes and fixes, with the level cap raised to 30. We’ll have all the details here tomorrow .','https://us.forums.blizzard.com/en/wow/t/beta-update-maintenance-october-1/2367661','blue','官方論壇',1790874773,1792404656,1792441144,'','[{"n":1,"at":1790813850,"user":"Kaivax","text":"Tomorrow morning PDT, we will take the WoW Forever Beta offline for maintenance. Several hours later, the Beta will resume with an updated build that includes changes and fixes, with the level cap raised to 30. We’ll have all the details here tomorrow .","url":"https://us.forums.blizzard.com/en/wow/t/beta-update-maintenance-october-1/2367661/1"},{"n":191,"at":1790874773,"user":"Kaivax","text":"We think we’ll take the Beta offline in about 45 minutes. See you on the other side!","url":"https://us.forums.blizzard.com/en/wow/t/beta-update-maintenance-october-1/2367661/191"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2363282','Realm is full','We looked into this, and found an issue that was causing the queue to fill, and we just fixed the issue. Thanks for testing with us!','https://us.forums.blizzard.com/en/wow/t/realm-is-full/2363282','blue','官方論壇',1790531876,1792404656,1792441144,'','[{"n":19,"at":1790531876,"user":"Kaivax","text":"We looked into this, and found an issue that was causing the queue to fill, and we just fixed the issue. Thanks for testing with us!","url":"https://us.forums.blizzard.com/en/wow/t/realm-is-full/2363282/19"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2362048','Beta Realm Restarts Incoming - Sept. 25','To implement fixes that should address stability issues, we will shutdown and restart the Beta in the next few minutes. The maintenance period should be very brief.','https://us.forums.blizzard.com/en/wow/t/beta-realm-restarts-incoming-sept-25/2362048','blue','官方論壇',1790359154,1792404656,1792441144,'','[{"n":1,"at":1790359154,"user":"Kaivax","text":"To implement fixes that should address stability issues, we will shutdown and restart the Beta in the next few minutes. The maintenance period should be very brief.","url":"https://us.forums.blizzard.com/en/wow/t/beta-realm-restarts-incoming-sept-25/2362048/1"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2361831','Game is unplayable today','We’re tracking server issues that are affecting some Beta testers, and our fix for this will almost certainly result in restarting servers today. Thank you for these reports.','https://us.forums.blizzard.com/en/wow/t/game-is-unplayable-today/2361831','blue','官方論壇',1790354846,1792404656,1792441144,'','[{"n":23,"at":1790354846,"user":"Kaivax","text":"We’re tracking server issues that are affecting some Beta testers, and our fix for this will almost certainly result in restarting servers today. Thank you for these reports.","url":"https://us.forums.blizzard.com/en/wow/t/game-is-unplayable-today/2361831/23"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2360739','WoW Forever Beta - Account Actions For Name Violations','We are in the process of issuing forced name changes to characters found to be in violation of our character naming policies that were created in the Forever Beta. Additionally, we have removed beta access for some users who created names that were far outside of our Code of Conduct. The use of dual…','https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-account-actions-for-name-violations/2360739','blue','官方論壇',1790290265,1792404656,1792441144,'','[{"n":1,"at":1790290265,"user":"Fwoibles","text":"We are in the process of issuing forced name changes to characters found to be in violation of our character naming policies that were created in the Forever Beta. Additionally, we have removed beta access for some users who created names that were far outside of our Code of Conduct. The use of dual…","url":"https://us.forums.blizzard.com/en/wow/t/wow-forever-beta-account-actions-for-name-violations/2360739/1"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2360489','Beta Realm Maintenance is Underway - September 24','We took the Beta down for maintenance and to deploy a new build. We don’t have an ETA just yet, but it should take at least a couple of hours. We’ll have a full change log (development notes) as well as updated known issues post here soon.','https://us.forums.blizzard.com/en/wow/t/beta-realm-maintenance-is-underway-september-24/2360489','blue','官方論壇',1790279455,1792404656,1792441144,'','[{"n":1,"at":1790279455,"user":"Kaivax","text":"We took the Beta down for maintenance and to deploy a new build. We don’t have an ETA just yet, but it should take at least a couple of hours. We’ll have a full change log (development notes) as well as updated known issues post here soon.","url":"https://us.forums.blizzard.com/en/wow/t/beta-realm-maintenance-is-underway-september-24/2360489/1"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2359185','Auto-shoot Bug and Fix Incoming','We’ve been tracking an issue in the WoW Forever Beta where the 0.5-second cast time that precedes a Hunter’s auto-shot or the use of a wand is not functioning properly. Due to a bug, these auto-shots are currently incurring a much shorter cast time, which in practice means that Hunters and wand use…','https://us.forums.blizzard.com/en/wow/t/auto-shoot-bug-and-fix-incoming/2359185','blue','官方論壇',1790180971,1792404656,1792441144,'','[{"n":1,"at":1790180971,"user":"Kaivax","text":"We’ve been tracking an issue in the WoW Forever Beta where the 0.5-second cast time that precedes a Hunter’s auto-shot or the use of a wand is not functioning properly. Due to a bug, these auto-shots are currently incurring a much shorter cast time, which in practice means that Hunters and wand use…","url":"https://us.forums.blizzard.com/en/wow/t/auto-shoot-bug-and-fix-incoming/2359185/1"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2358655','Beta Client Update - September 22','A few moments ago, we made a new client build available to Beta testers: WoW Forever 1.60.1 Build 69977 Exit the Beta, go to your Battle.net App, and update your client to this new build to test fixes for: Fixed some display issues and stability issues on Macs. Controller navigation should now w…','https://us.forums.blizzard.com/en/wow/t/beta-client-update-september-22/2358655','blue','官方論壇',1790124888,1792404656,1792441144,'','[{"n":1,"at":1790124888,"user":"Kaivax","text":"A few moments ago, we made a new client build available to Beta testers: WoW Forever 1.60.1 Build 69977 Exit the Beta, go to your Battle.net App, and update your client to this new build to test fixes for: Fixed some display issues and stability issues on Macs. Controller navigation should now w…","url":"https://us.forums.blizzard.com/en/wow/t/beta-client-update-september-22/2358655/1"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2354050','[Mac] 8 different graphics bugs, each isolated to one setting — with repro steps for each','I just want to thank you and others who have provided us with such incredibly detailed and useful reporting. We have multiple different analyses (and potential fixes) for Mac issues underway, and posts like yours are extremely helpful.','https://us.forums.blizzard.com/en/wow/t/mac-8-different-graphics-bugs-each-isolated-to-one-setting-%E2%80%94-with-repro-steps-for-each/2354050','blue','官方論壇',1790097057,1792404656,1792441144,'','[{"n":97,"at":1790097057,"user":"Kaivax","text":"I just want to thank you and others who have provided us with such incredibly detailed and useful reporting. We have multiple different analyses (and potential fixes) for Mac issues underway, and posts like yours are extremely helpful.","url":"https://us.forums.blizzard.com/en/wow/t/mac-8-different-graphics-bugs-each-isolated-to-one-setting-%E2%80%94-with-repro-steps-for-each/2354050/97"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2357451','"Character with that name already exists"','Hopping onto the most prominent of several threads about this– When reporting an issue like this, please provide the name of the Beta character that you’re locked out of, and if possible, the exact time you were last successfully playing the character (and got disconnected). That will help us narr…','https://us.forums.blizzard.com/en/wow/t/character-with-that-name-already-exists/2357451','blue','官方論壇',1790095484,1792404656,1792441144,'','[{"n":104,"at":1790094860,"user":"Kaivax","text":"Hopping onto the most prominent of several threads about this– When reporting an issue like this, please provide the name of the Beta character that you’re locked out of, and if possible, the exact time you were last successfully playing the character (and got disconnected). That will help us narr…","url":"https://us.forums.blizzard.com/en/wow/t/character-with-that-name-already-exists/2357451/104"},{"n":105,"at":1790094999,"user":"Kaivax","text":"About the same time you posted this, a Senior Game Producer told me that he wants to restart Beta realms today. Good thinkin’.","url":"https://us.forums.blizzard.com/en/wow/t/character-with-that-name-already-exists/2357451/105"},{"n":116,"at":1790095484,"user":"Kaivax","text":"Gathering as much information as possible, so that we can be sure of our understanding of both the issue and our fix for it. Thank you for your patience. We recognize that Beta testing is very different than playing a live game.","url":"https://us.forums.blizzard.com/en/wow/t/character-with-that-name-already-exists/2357451/116"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2353697','A Firm Response unable to progress','Confirming that we implemented fixes for this earlier. The issue was: The event that takes place during “A Firm Response” would become stuck and Windshaper Skyborne on Zephras Isle could not proceed. You’d walk up to talk to Belathaan Brightwish near the Shrine of Akir on Zephras to start the event…','https://us.forums.blizzard.com/en/wow/t/a-firm-response-unable-to-progress/2353697','blue','官方論壇',1790026848,1792404656,1792441144,'','[{"n":37,"at":1790026848,"user":"Kaivax","text":"Confirming that we implemented fixes for this earlier. The issue was: The event that takes place during “A Firm Response” would become stuck and Windshaper Skyborne on Zephras Isle could not proceed. You’d walk up to talk to Belathaan Brightwish near the Shrine of Akir on Zephras to start the event…","url":"https://us.forums.blizzard.com/en/wow/t/a-firm-response-unable-to-progress/2353697/37"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2352142','Unable to launch WoW Forever','Just want to clarify that this discussion forum is accessible by all players with an active WoW subscription. I’m not a qualified tech supporter by any stretch, but I had that issue one time following an inelegant shutdown due to a sudden power outage. The solution for me in that case was to go t…','https://us.forums.blizzard.com/en/wow/t/unable-to-launch-wow-forever/2352142','blue','官方論壇',1789764381,1792404656,1792441144,'','[{"n":130,"at":1789764381,"user":"Kaivax","text":"Just want to clarify that this discussion forum is accessible by all players with an active WoW subscription. I’m not a qualified tech supporter by any stretch, but I had that issue one time following an inelegant shutdown due to a sudden power outage. The solution for me in that case was to go t…","url":"https://us.forums.blizzard.com/en/wow/t/unable-to-launch-wow-forever/2352142/130"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2352429','Almost there!','We’re seeing a lot of people waiting to get into the Beta. Thank you for joining us! We’re working through a couple of final issues, and we hope to throw the doors open soon. Thank you for your patience!','https://us.forums.blizzard.com/en/wow/t/almost-there/2352429','blue','官方論壇',1789678379,1792404656,1792441144,'','[{"n":1,"at":1789675326,"user":"Kaivax","text":"We’re seeing a lot of people waiting to get into the Beta. Thank you for joining us! We’re working through a couple of final issues, and we hope to throw the doors open soon. Thank you for your patience!","url":"https://us.forums.blizzard.com/en/wow/t/almost-there/2352429/1"},{"n":226,"at":1789678379,"user":"Kaivax","text":"We almost have the doors thrown open. It’s been more of a smooth and slow opening of the doors than a throw.","url":"https://us.forums.blizzard.com/en/wow/t/almost-there/2352429/226"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('stress-test-oct-21','《魔獸世界：永恆》壓力測試改期：台灣時間 10/22（四）05:00 開始','官方論壇 10/17 公告，壓力測試從美西 10/19 改到 10/21 下午 2 點，台灣時間 10/22（四）清晨 5 點開始。封測先離線，結束後角色、名稱、公會全部清除，10/28 開放名稱預約；不用訂閱就能參加。','/news/stress-test-oct-21','off','本站整理',1792404000,1792404656,1793030455,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/ev/EVFNPP5S77ZN1789667878336.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('forever-regions','《魔獸世界：永恆》會跨區嗎？台灣、韓國、中國分區整理（附封測普查數據）','正式上市不開放跨區，台灣、韓國各是一個地區，中國以官方公告為準；同一區會優先排同語言的玩家。封測普查裡韓文名字的角色，聯盟 6.5%、部落 4.9%。亞洲不禁 G 團。','/news/forever-regions','site','本站整理',1792409400,1792409179,1793030455,'','');
