INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2349672','Krol’dok Stronghold','We’ve spotted one item from BlizzCon that we want to clarify. In various places, the new Krol’dok Stronghold dungeon is listed alongside an incorrect level range. In WoW: Forever, Krol’dok Stronghold will be for levels 40-45. Here’s the full list of nine new dungeons coming in WoW: Forever. D…','https://us.forums.blizzard.com/en/wow/t/krol%E2%80%99dok-stronghold/2349672','blue','官方論壇',1789433967,1792441144,1792441144,'','[{"n":1,"at":1789433967,"user":"Kaivax","text":"We’ve spotted one item from BlizzCon that we want to clarify. In various places, the new Krol’dok Stronghold dungeon is listed alongside an incorrect level range. In WoW: Forever, Krol’dok Stronghold will be for levels 40-45. Here’s the full list of nine new dungeons coming in WoW: Forever. D…","url":"https://us.forums.blizzard.com/en/wow/t/krol%E2%80%99dok-stronghold/2349672/1"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24301455','探索全新《魔獸世界：永恆》地城','探索在《魔獸世界：永恆》中遍布東部王國與卡林多的全新地城，等級範圍橫跨 13 級至 60 級。前往熟悉城市的地底，進入封閉已久的大門，探索艾澤拉斯中久未發掘的各個角落。','https://news.blizzard.com/zh-tw/article/24301455/%E6%8E%A2%E7%B4%A2%E5%85%A8%E6%96%B0%E3%80%8A%E9%AD%94%E7%8D%B8%E4%B8%96%E7%95%8C%EF%BC%9A%E6%B0%B8%E6%81%86%E3%80%8B%E5%9C%B0%E5%9F%8E','off','最新消息',1792515600,1792516556,1793030455,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/25/250GH36KBYZ81792014008662.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24303009','《魔獸世界：永恆》團隊副本概覽：地點、團隊副本規模，以及前置條件','地深獸穴、海加爾山之巔，以及奧妮克希亞巢穴都將於 12 月 10 日在《魔獸世界：永恆》中開放。了解這些 60 級團隊副本的地點，所需的玩家數量，以及如何獲得進入奧妮克希亞巢穴所需的「龍火護符」。','https://news.blizzard.com/zh-tw/article/24303009/%E3%80%8A%E9%AD%94%E7%8D%B8%E4%B8%96%E7%95%8C%EF%BC%9A%E6%B0%B8%E6%81%86%E3%80%8B%E5%9C%98%E9%9A%8A%E5%89%AF%E6%9C%AC%E6%A6%82%E8%A6%BD%EF%BC%9A%E5%9C%B0%E9%BB%9E%E3%80%81%E5%9C%98%E9%9A%8A%E5%89%AF%E6%9C%AC%E8%A6%8F%E6%A8%A1%EF%BC%8C%E4%BB%A5%E5%8F%8A%E5%89%8D%E7%BD%AE%E6%A2%9D%E4%BB%B6','off','最新消息',1792522800,1792523756,1793030455,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/i8/I8PRYL2YKVSR1792099058746.png','');
