INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24303866','保留你的《魔獸世界：永恆》角色名稱','準備在艾澤拉斯名留青史！《魔獸世界：永恆》搶先名稱預定可於 10 月 28 日至 11 月 4 日期間完成，提供機會可提早預定最多三個角色的名稱。','https://news.blizzard.com/zh-tw/article/24303866/%E4%BF%9D%E7%95%99%E4%BD%A0%E7%9A%84%E3%80%8A%E9%AD%94%E7%8D%B8%E4%B8%96%E7%95%8C%EF%BC%9A%E6%B0%B8%E6%81%86%E3%80%8B%E8%A7%92%E8%89%B2%E5%90%8D%E7%A8%B1','off','最新消息',1792530000,1792530955,1793030455,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/cj/CJUNEMGJNYPJ1792458573707.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('site-update-1021','阿莫比網站更新（10/21）：專業技能資料庫上線、盜賊技能補齊','新增專業技能資料庫（十二個專業、2,196 個配方，永恆新增 948 個）；盜賊補上毒藥和開鎖、獵人補上寵物技能，天賦的主動技能（例如截肢）也放上來了；副本資料庫加上官方 10/21 公布的團隊副本和新地城；新聞頁改成中文翻譯在上。','/news/site-update-1021','site','網站更新',1792583400,1792583573,1793030455,'','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2388547','Testing WoW Forever Today - October 21','The WoW Forever Beta is going offline in a few minutes. In this region, the Stress Test will begin at 2:00 p.m. PDT. To prepare for that, go to your Battle.net App and look for Stress Test under the Game Version selector on the WoW Forever playscreen. It should look like this: [image]','https://us.forums.blizzard.com/en/wow/t/testing-wow-forever-today-october-21/2388547','blue','官方論壇',1792600134,1792600256,1793030455,'','[{"n":1,"at":1792600134,"user":"Kaivax","text":"The WoW Forever Beta is going offline in a few minutes. In this region, the Stress Test will begin at 2:00 p.m. PDT. To prepare for that, go to your Battle.net App and look for Stress Test under the Game Version selector on the WoW Forever playscreen. It should look like this: [image]","url":"https://us.forums.blizzard.com/en/wow/t/testing-wow-forever-today-october-21/2388547/1"}]');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24301516','在《魔獸世界：永恆》齊聚於營火旁','《魔獸世界：永恆》的紮營系統能讓玩家創造一座可共享的營地，讓大家休息、製作，並透過專業技能製作的各種功能獲得實用增益。一開始先從烹飪專業技能的基礎營火開始，這個系統會賦予冒險者全新的理由，在探索艾澤拉斯的過程中一起備戰，相互連結。','https://news.blizzard.com/zh-tw/article/24301516/%E5%9C%A8%E3%80%8A%E9%AD%94%E7%8D%B8%E4%B8%96%E7%95%8C%EF%BC%9A%E6%B0%B8%E6%81%86%E3%80%8B%E9%BD%8A%E8%81%9A%E6%96%BC%E7%87%9F%E7%81%AB%E6%97%81','off','最新消息',1792602000,1792602956,1793030455,'https://bnetcmsus-a.akamaihd.net/cms/blog_thumbnail/b0/B0HPKSFCFCDC1792455657405.png','');
INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('b2389150','Forever Beta Will Return Shortly','Good evening folks, We hit a small snag while turning the WoW Forever Beta back online. We’re working right now to get it back. In the meantime, you can speed this up by fully exiting the Battle.net Desktop App to force the update to happen manually. Thanks!','https://us.forums.blizzard.com/en/wow/t/forever-beta-will-return-shortly/2389150','blue','官方論壇',1792633604,1792634456,1793030455,'','[{"n":1,"at":1792633604,"user":"Zorbrix-83447","text":"Good evening folks, We hit a small snag while turning the WoW Forever Beta back online. We’re working right now to get it back. In the meantime, you can speed this up by fully exiting the Battle.net Desktop App to force the update to happen manually. Thanks!","url":"https://us.forums.blizzard.com/en/wow/t/forever-beta-will-return-shortly/2389150/1"}]');
