INSERT INTO "news" ("id","title","summary","url","kind","category","published_at","first_seen_at","updated_at","image","extra") VALUES('24304076','觀看《魔獸世界：永恆》Podcast Ep.1','在《魔獸世界：永恆》的首集 Podcast 節目中，加入資深遊戲設計師 Josh "Aggrend" Greenfield、首席經典版設計師 Tim Jones，以及內容創作者 Countdown To Classic 與 Xaryu 的討論吧。','https://news.blizzard.com/zh-tw/article/24304076/podcast-ep-1','off','最新消息',1790266500,1793003750,1793030455,'https://bnetcmsus-a.akamaihd.net/cms/blog_header/ep/EPSTZUAPQ9TV1790269181996.png','');
